@layer theme, base, components, utilities;

@layer components {
  /* Reading progress: a 2px ember line under the sticky header. */
  [data-slot="reading-progress"] { position: sticky; top: 68px; z-index: 19; height: 2px; margin-bottom: -2px; pointer-events: none; }
  [data-slot="reading-progress"] > span { display: block; height: 100%; background: var(--k-hi); transform-origin: left center; }
  [data-slot="article-author"] { display: flex; align-items: flex-start; gap: 16px; padding-top: 28px; border-top: 1px solid var(--k-line-strong); }
  [data-slot="article-next"] {
    display: inline-flex; align-items: center; justify-self: start; gap: 10px; min-height: 48px; padding: 0 20px; border-radius: var(--k-btn-radius);
    background: var(--k-accent); color: var(--k-accent-ink); font-size: 15px; font-weight: 500; text-decoration: none;
  }
  [data-slot="article-next"] svg { width: 16px; height: 16px; transition: translate var(--duration-normal) var(--ease-out); }
  [data-slot="article-next"]:hover svg { translate: 3px 0; }
  [data-slot="article-next"]:focus-visible { outline: 2px solid var(--k-focus, var(--k-hi)); outline-offset: 3px; }
  [data-slot="article-related"] { display: grid; gap: 16px; margin: 0; padding: 0; list-style: none; }
  @container (min-width: 760px) { [data-slot="article-related"] { grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 20px; } }
  [data-slot="article-related"] a {
    display: grid; align-content: start; gap: 10px; height: 100%; padding: 22px; border-radius: var(--k-radius-lg); background: var(--k-surface); box-shadow: 0 0 0 1px var(--k-line);
    color: inherit; text-decoration: none; transition: box-shadow var(--duration-fast) var(--ease-out), translate var(--duration-normal) var(--ease-out);
  }
  [data-slot="article-related"] a:hover { box-shadow: 0 0 0 1px var(--k-line-strong), var(--k-shadow); translate: 0 -2px; }
  [data-slot="article-related"] a:focus-visible { outline: 2px solid var(--k-focus, var(--k-hi)); outline-offset: 3px; }
  [data-slot="article-related-title"] { font-family: var(--k-display-font); font-size: 22px; line-height: 1.2; letter-spacing: calc(var(--k-display-track) / 2); }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="article-related"] a:hover { translate: none; }
  }
}

/* Shared by button.tsx, confirm-morph.tsx, expanding-button-group.tsx, field.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="loading-indicator"] {
    animation: caliper-spin var(--duration-loading) var(--ease-linear) infinite;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="loading-indicator"] {
      animation: none;
    }
  }
}

/* button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="button"] {
    transition-property: background-color, color, border-color;
    transition-duration: var(--duration-fast);
    transition-timing-function: var(--ease-out);
  }

  /* Button material. Raised to press: a lit top edge and a small lift; the
     press travels 1px down and swaps the lift for an inner shade. Only
     translate animates (release on the settle curve); shadows swap. */
  [data-slot="button"] {
    --b-bg: var(--raised);
    --b-bg-hover: var(--raised-hover);
    --b-bg-press: var(--raised-press);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-raised);
    --b-shadow-press: var(--shadow-raised-press);
    background-color: var(--b-bg);
    color: var(--b-fg);
    box-shadow: var(--b-shadow);
    transition-property: background-color, color, border-color, translate, scale;
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast),
      var(--duration-normal), var(--duration-normal);
    transition-timing-function:
      var(--ease-out), var(--ease-out), var(--ease-out), var(--ease-settle),
      var(--ease-settle);
  }
  [data-slot="button"][data-variant="default"] {
    --b-bg: var(--primary);
    --b-bg-hover: var(--primary-hover);
    --b-bg-press: var(--primary-press);
    --b-fg: var(--primary-foreground);
    --b-shadow: var(--shadow-accent);
    --b-shadow-press: var(--shadow-accent-press);
  }
  [data-slot="button"][data-variant="destructive"] {
    --b-bg: var(--danger-fill);
    --b-bg-hover: var(--danger-fill-hover);
    --b-bg-press: var(--danger-fill-press);
    --b-fg: var(--danger-fill-foreground);
    --b-shadow: var(--shadow-danger);
    --b-shadow-press: var(--shadow-danger-press);
  }
  [data-slot="button"][data-variant="ghost"] {
    --b-bg: transparent;
    --b-bg-hover: var(--muted);
    --b-bg-press: var(--muted);
    --b-fg: var(--muted-foreground);
    --b-shadow: none;
    --b-shadow-press: none;
  }
  @media (hover: hover) {
    [data-slot="button"]:hover {
      background-color: var(--b-bg-hover);
    }
    [data-slot="button"][data-variant="ghost"]:hover {
      color: var(--foreground);
    }
  }
  [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    translate: 0 var(--motion-press-travel);
    scale: var(--motion-press-scale);
    background-color: var(--b-bg-press);
    box-shadow: var(--b-shadow-press);
    transition-duration:
      var(--duration-fast), var(--duration-fast), var(--duration-fast), 90ms,
      90ms;
    transition-timing-function: var(--ease-out);
  }
  [data-slot="button"]:is(:disabled, [aria-disabled="true"]):not([aria-busy="true"]) {
    background-color: var(--sunken);
    color: var(--muted-foreground);
  }
  [data-slot="button"][data-variant="ghost"]:is(:disabled, [aria-disabled="true"]):not(
      [aria-busy="true"]
    ) {
    background-color: transparent;
    box-shadow: none;
  }
  /* Loading keeps the exact width: the label stays in flow but invisible. */
  [data-slot="button-label"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
  }
  /* Opacity, not visibility, so the label still names the button. */
  [data-slot="button-label"][data-hidden="true"] {
    opacity: 0;
  }
  [data-slot="button-busy"] {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
  }
  [data-slot="button-feedback"] {
    display: inline-flex;
    align-items: center;
    gap: inherit;
    overflow: clip;
    transition: width var(--duration-normal) var(--ease-out);
  }
  [data-slot="button-feedback-label"] {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    gap: inherit;
    width: max-content;
  }
  [data-slot="button-feedback-label"][data-enter="true"] {
    animation: caliper-feedback-enter var(--duration-normal) var(--ease-out);
  }

  [data-slot="button"][aria-busy="true"] {
    pointer-events: none;
  }
  [data-slot="button"][data-action-phase="error"] {
    color: var(--danger);
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="button"],
    [data-slot="button-feedback"] {
      transition: none;
    }
    [data-slot="button"]:active:not(:disabled):not([aria-disabled="true"]):not(
        [aria-busy="true"]
      ) {
      translate: none;
    }
    [data-slot="button-feedback-label"],
    [data-slot="button-feedback-label"][data-enter="true"] {
      animation: none;
    }
  }

  /* Toggle: pressed is recessed, as a toggled tool in a button group is. */
  /* Four attributes, so it wins over the group and toolbar pressed rules in any stylesheet order. */
  [data-slot="button"][data-variant="ghost"][data-toggle][aria-pressed="true"] {
    --b-bg: var(--raised-press);
    --b-bg-hover: var(--raised-press);
    --b-bg-press: var(--raised-press);
    --b-fg: var(--foreground);
    --b-shadow: var(--shadow-sunken);
    --b-shadow-press: var(--shadow-sunken);
  }
}

/* Shared by action-button.tsx, copy-button.tsx, hold-to-confirm.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Action button: every phase's label shares one grid cell, so the button
     is always as wide as its widest label and never shifts. */
  [data-slot="action-labels"] {
    display: inline-grid;
    justify-items: center;
  }
  [data-slot="action-label"] {
    grid-area: 1 / 1;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    visibility: hidden;
    opacity: 0;
    transition: opacity var(--duration-fast) var(--ease-out), visibility 0s linear var(--duration-fast);
  }
  [data-slot="action-label"][data-active="true"] {
    visibility: visible;
    opacity: 1;
    transition: opacity var(--duration-fast) var(--ease-out), visibility 0s;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="action-label"],
    [data-slot="action-label"][data-active="true"] {
      transition: none !important;
    }
  }
}

/* copy-button.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* Copy button: the icon swaps in place; a small inverse ticket says what
     was copied. A failure keeps the ticket open with the value selected. */
  [data-slot="copy-icon"] {
    position: relative;
    display: inline-grid;
    width: 16px;
    height: 16px;
  }
  [data-slot="copy-icon"] svg {
    grid-area: 1 / 1;
    transition:
      opacity var(--duration-fast) var(--ease-out),
      scale var(--duration-normal) var(--ease-settle);
  }
  [data-slot="copy-icon"] svg:last-child,
  [data-slot="copy-icon"][data-copied="true"] svg:first-child {
    opacity: 0;
    scale: 0.6;
  }
  [data-slot="copy-icon"][data-copied="true"] svg:last-child {
    opacity: 1;
    scale: 1;
  }
  [data-slot="copy-ticket"] {
    position: absolute;
    right: 0;
    bottom: calc(100% + 8px);
    z-index: 30;
    pointer-events: none;
  }
  [data-slot="copy-ticket-body"] {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 6px 10px;
    border-radius: 8px;
    background: var(--primary);
    color: var(--primary-foreground);
    font-size: 12px;
    line-height: 16px;
    font-weight: 500;
    white-space: nowrap;
    box-shadow: var(--shadow-feedback);
    animation: caliper-ticket-in var(--duration-normal) var(--ease-out);
  }
  [data-slot="copy-ticket-body"] svg {
    width: 14px;
    height: 14px;
  }
  [data-slot="copy-ticket-body"][data-tone="error"] {
    display: grid;
    width: min(320px, calc(100vw - 32px));
    gap: 8px;
    padding: 10px;
    white-space: normal;
    background: var(--elevated);
    color: var(--danger);
    box-shadow: var(--shadow-overlay), inset 0 0 0 1px var(--border);
    pointer-events: auto;
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="copy-icon"] svg {
      transition: none;
    }
    [data-slot="copy-ticket-body"] {
      animation: none;
    }
  }
  @keyframes caliper-ticket-in {
    from {
      opacity: 0;
      translate: 0 4px;
    }
  }
}

/* footer-block.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* ── Footer ───────────────────────────────────────── */
  [data-slot="footer-brand"] {
    margin: 0; font-family: var(--k-display-font); font-weight: var(--k-display-weight); font-stretch: var(--k-display-stretch);
    font-variation-settings: "wdth" var(--k-display-wdth, 100); text-transform: var(--k-display-case);
    letter-spacing: calc(var(--k-display-track) / 2); font-size: 28px; line-height: 1;
  }
  /* A label, not code: Geist at the label step (DESIGN-SYSTEM.md keeps mono for code, commands and keycaps). */
  [data-slot="footer-heading"] { margin: 0; font-size: 13px; line-height: 18px; font-weight: 500; color: var(--k-muted); }
  [data-slot="footer-block-link"] { font-size: 15px; color: var(--k-ink); text-decoration: none; text-underline-offset: 4px; }
  [data-slot="footer-block-link"]:hover { text-decoration: underline; text-decoration-color: var(--k-hi); }
  [data-slot="footer-block-link"]:focus-visible { outline: 2px solid var(--k-focus); outline-offset: 3px; border-radius: 3px; }
  [data-slot="footer-field"] {
    display: flex; align-items: center; gap: 6px; height: 50px; padding: 5px 5px 5px 16px;
    border-radius: var(--k-btn-radius); background: var(--k-surface); box-shadow: inset 0 0 0 1px var(--k-line-strong);
    transition: box-shadow var(--duration-fast) var(--ease-out);
  }
  [data-slot="footer-field"]:focus-within { box-shadow: inset 0 0 0 2px var(--k-focus); }
  [data-slot="footer-field"][data-invalid] { box-shadow: inset 0 0 0 2px var(--k-danger); }
  [data-slot="footer-field"] input { flex: 1; min-width: 0; border: 0; background: transparent; color: var(--k-ink); font-size: 15px; outline: none; }
  [data-slot="footer-field"] input::placeholder { color: var(--k-muted); }
  [data-slot="footer-field"] button {
    display: grid; place-items: center; width: 40px; height: 40px; flex: none; border-radius: calc(var(--k-btn-radius) - 4px);
    background: var(--k-accent); color: var(--k-accent-ink); cursor: pointer;
  }
  [data-slot="footer-field"] button:focus-visible { outline: 2px solid var(--k-focus); outline-offset: 2px; }
  [data-slot="footer-field"] button:disabled { opacity: 0.6; cursor: progress; }
  [data-slot="footer-status-dot"] { width: 8px; height: 8px; border-radius: 999px; background: var(--success, #0b7643); box-shadow: 0 0 0 3px color-mix(in srgb, var(--success, #0b7643) 22%, transparent); }
  [data-slot="footer-wordmark"] {
    margin: 0 0 -0.16em; overflow: hidden;
    font-family: var(--k-display-font); font-weight: var(--k-display-weight); font-stretch: var(--k-display-stretch);
    font-variation-settings: "wdth" var(--k-display-wdth, 100); text-transform: var(--k-display-case);
    font-size: var(--wordmark-size, clamp(72px, 21cqi, 300px)); line-height: 0.82; letter-spacing: -0.06em; white-space: nowrap;
    color: var(--k-ink); user-select: none;
  }
  [data-slot="footer-wordmark"] > span { display: inline-block; padding-right: 0.04em; }
  [data-slot="footer-wordmark"] { font-weight: 700; }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="footer-field"] { transition: none; }
  }
}

/* Shared by changelog-template.tsx, docs-template.tsx, landing-template.tsx, pricing-template.tsx, site-header.tsx, template-page.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="skip-link"] {
    position: absolute;
    top: 0.5rem;
    left: 0.5rem;
    z-index: 50;
    padding: 0.5rem 0.75rem;
    border-radius: var(--radius-control);
    background: var(--foreground);
    color: var(--background);
    font-size: 0.875rem;
    transform: translateY(-200%);
  }
  [data-slot="skip-link"]:focus {
    transform: none;
    outline: 2px solid var(--ring);
    outline-offset: 2px;
  }
  [data-slot="skip-link"] {
    position: absolute; left: 12px; top: -48px; z-index: 50; padding: 8px 12px; border-radius: 12px;
    background: var(--foreground); color: var(--background); font-size: 13px; text-decoration: none;
  }
  [data-slot="skip-link"]:focus-visible { top: 12px; outline: 2px solid var(--ring); outline-offset: 2px; }
  @media print {
    [data-slot="skip-link"] { display: none !important; }
  }
}

/* template-page.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="template-outline"] { min-width: 0; }
  [data-slot="template-outline-label"] { display: none; margin: 0 0 12px; font-family: var(--font-mono, monospace); font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--k-muted); }
  [data-slot="template-outline"] > [data-slot="template-outline-list"] { display: none; }
  @container (min-width: 960px) {
    [data-slot="template-outline"] { position: sticky; top: 96px; align-self: start; }
    [data-slot="template-outline-label"], [data-slot="template-outline"] > [data-slot="template-outline-list"] { display: block; }
    [data-slot="template-outline-fold"] { display: none; }
  }
  [data-slot="template-outline-list"] { display: grid; gap: 2px; margin: 0; padding: 0; list-style: none; }
  [data-slot="template-outline-list"] a {
    position: relative; display: flex; gap: 8px; padding: 6px 0 6px 14px; font-size: 14px; line-height: 20px; color: var(--k-muted); text-decoration: none;
    transition: color var(--duration-fast) var(--ease-out);
  }
  [data-slot="template-outline-list"] a::before { content: ""; position: absolute; left: 0; top: 6px; bottom: 6px; width: 2px; border-radius: 2px; background: var(--k-line); transition: background-color var(--duration-normal) var(--ease-out); }
  [data-slot="template-outline-list"] a:hover { color: var(--k-ink); }
  [data-slot="template-outline-list"] a[aria-current] { color: var(--k-ink); }
  [data-slot="template-outline-list"] a[aria-current]::before { background: var(--k-hi); }
  [data-slot="template-outline-list"] a:focus-visible { outline: 2px solid var(--k-focus, var(--k-hi)); outline-offset: 2px; border-radius: 4px; }
  [data-slot="template-outline-number"] { flex: none; min-width: 1.6em; font-variant-numeric: tabular-nums; }
  [data-slot="template-outline-fold"] { border-radius: var(--k-radius); background: var(--k-surface); box-shadow: 0 0 0 1px var(--k-line); }
  [data-slot="template-outline-fold"] > summary { display: flex; align-items: center; justify-content: space-between; min-height: 48px; padding: 0 16px; font-size: 14px; font-weight: 500; cursor: pointer; list-style: none; }
  [data-slot="template-outline-fold"] > summary::-webkit-details-marker { display: none; }
  [data-slot="template-outline-fold"] > summary::after { content: "+"; font-size: 18px; color: var(--k-muted); }
  [data-slot="template-outline-fold"][open] > summary::after { content: "–"; }
  [data-slot="template-outline-fold"] > summary:focus-visible { outline: 2px solid var(--k-focus, var(--k-hi)); outline-offset: 2px; border-radius: var(--k-radius); }
  [data-slot="template-outline-fold"] > [data-slot="template-outline-list"] { padding: 0 16px 12px; }
  @media print {
    [data-slot="template-outline"] { display: none !important; }
  }
}
